/* Play navigation is view state only. Native controls, records and rule calculations remain authoritative. */
(()=>{'use strict';
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),L=(en,ko)=>`<span data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(window.UKI18n?.language==='en'?en:ko)}</span>`,states=new Map();let serial=0;
const account=()=>window.AccountParity?.account?.id||'',gangFor=id=>data.gangs.find(g=>g.id===id),txt=(en,ko)=>window.UKI18n?.language==='en'?en:ko;
function el(tag,cls){const n=document.createElement(tag);if(cls)n.className=cls;return n;}
function append(parent,...nodes){for(const n of nodes)if(n)parent.append(n);}
function view(c,s){return {id:c?.id||'skirmish',s,mode:c?'campaign':'skirmish',c};}
function key(v){return JSON.stringify([account(),v.mode,v.id,v.s.id]);}
function state(v){const k=key(v);if(!states.has(k))states.set(k,{tab:'roster',side:null,units:{},sections:new Map()});return states.get(k);}
function sourceAction(button,callbacks){const index=callbacks.length;callbacks.push(()=>{if(button.isConnected&&!button.disabled)button.click();});return index;}
function unitView(f,row){return {...f,loadouts:(f.loadouts||[]).map(l=>({...l,active:l.id===row.loadoutId}))};}
function heading(v,source){const h=el('header','bp-heading'),title=el('h1');title.dataset.userText='';title.textContent=v.s.scenario||v.s.name||txt('Battle','전투');append(h,source,title);return h;}
function shell(v,root){
 const ui=state(v),id='bp-'+(++serial),callbacks=[],host=el('section','bp-workspace');host.dataset.bpMode=v.mode;host.dataset.bpKey=key(v);
 const tabs=[['roster','Roster','로스터'],['round',v.c?'Round & results':'Round & score',v.c?'라운드·결과':'라운드·점수'],['mission','Mission','미션'],['operations','Notes & controls','메모·운영']],bar=el('div','bp-bar'),nav=el('nav','bp-tabs'),brief=el('button','bp-brief');
 nav.setAttribute('role','tablist');nav.setAttribute('aria-label',txt('Battle categories','전투 카테고리'));
 brief.type='button';brief.innerHTML=`<strong data-i18n-ignore>R${E(v.s.round||1)}</strong>${!v.c?`<span data-i18n-ignore>${v.s.participants.map(p=>E(p.vp||0)).join(' : ')}</span>`:''}`;brief.setAttribute('aria-label',txt('Open round controls','라운드 조작 열기'));brief.dataset.bpTab='round';
 const panels=new Map();for(const [tab,en,ko]of tabs){const b=el('button');b.type='button';b.id=id+'-tab-'+tab;b.dataset.bpTab=tab;b.setAttribute('role','tab');b.setAttribute('aria-controls',id+'-panel-'+tab);b.innerHTML=L(en,ko);nav.append(b);const p=el('section','bp-tab-panel');p.id=id+'-panel-'+tab;p.dataset.bpPanel=tab;p.setAttribute('role','tabpanel');p.setAttribute('aria-labelledby',b.id);p.tabIndex=0;panels.set(tab,p);}
 append(bar,nav,brief);host.append(bar,...panels.values());root.append(host);
 const select=tab=>{ui.tab=panels.has(tab)?tab:'roster';for(const [k,p]of panels)p.hidden=k!==ui.tab;for(const b of nav.querySelectorAll('[data-bp-tab]')){const on=b.dataset.bpTab===ui.tab;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;}};
 host.addEventListener('click',event=>{const b=event.target.closest('[data-bp-tab],[data-bp-action]');if(!b||b.disabled||!host.contains(b))return;event.preventDefault();if(b.dataset.bpTab)select(b.dataset.bpTab);else callbacks[Number(b.dataset.bpAction)]?.();});
 nav.addEventListener('keydown',event=>{const b=event.target.closest('[role=tab]');if(!b||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const list=[...nav.children],i=list.indexOf(b),next=event.key==='Home'?list[0]:event.key==='End'?list.at(-1):list[(i+(event.key==='ArrowLeft'?-1:1)+list.length)%list.length];select(next.dataset.bpTab);next.focus();});
 select(ui.tab);return {host,panels,ui,id,callbacks};
}
function roster(v,ctx,originals=[]){
 const {panels,ui,id,callbacks}=ctx,host=panels.get('roster'),sides=el('nav','bp-sides'),bodies=el('div','bp-rosters');sides.setAttribute('role','tablist');sides.setAttribute('aria-label',txt('Gangs','갱'));
 const teams=v.s.participants.map((p,i)=>{const g=gangFor(p.gangId),rows=[...(p.crew||[]).map(row=>({row,reserve:false})),...(v.c?p.reinforcements||[]:[]).map(row=>({row,reserve:true}))];return {p,g,i,rows};});
 if(ui.side==null||!teams[ui.side])ui.side=teams.find(t=>t.g?.id===data.selectedGang&&t.rows.length)?.i??teams.find(t=>t.rows.length)?.i??0;
 for(const {p,g,i,rows}of teams){const b=el('button');b.type='button';b.dataset.bpSide=String(i);b.id=id+'-side-tab-'+i;b.setAttribute('role','tab');b.setAttribute('aria-controls',id+'-side-'+i);b.innerHTML=`<span data-user-text>${E(p.name||g?.name||txt('Gang','갱'))}</span><small>${rows.length}</small>`;sides.append(b);
  const team=el('section','bp-roster-side');team.dataset.bpSidePanel=String(i);team.id=id+'-side-'+i;team.setAttribute('role','tabpanel');team.setAttribute('aria-labelledby',b.id);
  const layout=el('div','bp-side-content'),units=el('nav','bp-units'),cards=el('div','bp-unit-panels');units.setAttribute('role','tablist');units.setAttribute('aria-label',txt('Fighters','파이터'));
  for(const {row,reserve}of rows){const f=g?.fighters.find(f=>f.id===row.fighterId);if(!f)continue;const uid=String(row.fighterId),tab=el('button');tab.type='button';tab.dataset.bpUnit=uid;tab.id=id+'-unit-tab-'+i+'-'+units.children.length;tab.setAttribute('role','tab');tab.setAttribute('aria-controls',id+'-unit-'+i+'-'+units.children.length);tab.innerHTML=`<span data-user-text>${E(f.name)}</span>${reserve?`<small>${L('Reserve','증원 대기')}</small>`:''}`;units.append(tab);
   let panel=originals.find(n=>n.dataset.bpSide===String(i)&&n.dataset.bpFighter===uid);if(panel){panel.open=true;panel.querySelector(':scope > summary')?.setAttribute('hidden','');}else{panel=el('section');panel.innerHTML=window.MMPlayMode?.card(unitView(f,row),g)||'';}
   panel.classList.add('bp-unit-panel');panel.dataset.bpUnitPanel=uid;panel.id=tab.getAttribute('aria-controls');panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',tab.id);
   if(reserve){const badge=el('p','bp-reserve-label');badge.innerHTML=L('Reserve deck','증원 대기');panel.prepend(badge);}
   if(v.c&&!reserve){const original=[...ctx.nativeParticipants[i]?.querySelectorAll('[data-cp]')||[]].filter(n=>n.dataset.id===uid&&['fighter-actions','fighter-activate'].includes(n.dataset.cp));if(original.length){const actions=el('div','bp-unit-actions');for(const source of original){const button=el('button','btn small');button.type='button';button.innerHTML=source.dataset.cp==='fighter-actions'?L('State & actions','상태·행동'):source.innerHTML;button.dataset.bpAction=String(sourceAction(source,callbacks));button.disabled=source.disabled||!window.MMCampaignSessionData?.canEdit(v.c);actions.append(button);}panel.prepend(actions);}}
   if(v.c){const tags=[];if(row.status&&!['Ready','Active'].includes(row.status))tags.push(L(row.status,window.UKI18n?.t(row.status,'ko')||row.status));for(const [key,en,ko]of [['wounds','Wounds','상처'],['fleshWounds','Flesh wounds','살점 부상']])if(Number(row[key])>0)tags.push(L(en,ko)+' '+E(row[key]));if(Array.isArray(row.conditions))for(const condition of row.conditions)tags.push(L(String(condition),window.UKI18n?.t(String(condition),'ko')||String(condition)));if(tags.length){const status=el('div','bp-battle-conditions');status.innerHTML=tags.map(t=>'<span>'+t+'</span>').join('');panel.prepend(status);}}
   for(const fold of panel.querySelectorAll('.pm-collapsible[data-play-section]')){const k=JSON.stringify([i,uid,fold.dataset.playSection]);fold.open=ui.sections.get(k)||false;fold.addEventListener('toggle',()=>{if(fold.isConnected)ui.sections.set(k,fold.open);});}
   cards.append(panel);
  }
  if(!cards.children.length){const empty=el('p','bp-empty');empty.innerHTML=L('No crew entered','크루 명단 미입력');cards.append(empty);}
  append(layout,units,cards);team.append(layout);bodies.append(team);
  const selectUnit=unit=>{const tabs=[...units.children];if(!tabs.some(t=>t.dataset.bpUnit===unit))unit=tabs[0]?.dataset.bpUnit;ui.units[i]=unit;for(const t of tabs){const on=t.dataset.bpUnit===unit;t.setAttribute('aria-selected',String(on));t.tabIndex=on?0:-1;}for(const c of cards.querySelectorAll('[data-bp-unit-panel]'))c.hidden=c.dataset.bpUnitPanel!==unit;};
  units.addEventListener('click',e=>{const t=e.target.closest('[data-bp-unit]');if(t)selectUnit(t.dataset.bpUnit);});
  units.addEventListener('keydown',e=>{const t=e.target.closest('[role=tab]');if(!t||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();const list=[...units.children],at=list.indexOf(t),next=e.key==='Home'?list[0]:e.key==='End'?list.at(-1):list[(at+(['ArrowLeft','ArrowUp'].includes(e.key)?-1:1)+list.length)%list.length];selectUnit(next.dataset.bpUnit);next.focus();});selectUnit(ui.units[i]);
 }
 const selectSide=index=>{ui.side=Number(index);for(const b of sides.children){const on=Number(b.dataset.bpSide)===ui.side;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;}for(const body of bodies.children)body.hidden=Number(body.dataset.bpSidePanel)!==ui.side;};
 sides.addEventListener('click',e=>{const b=e.target.closest('[data-bp-side]');if(b)selectSide(b.dataset.bpSide);});sides.addEventListener('keydown',e=>{const b=e.target.closest('[role=tab]');if(!b||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const list=[...sides.children],at=list.indexOf(b),next=e.key==='Home'?list[0]:e.key==='End'?list.at(-1):list[(at+(e.key==='ArrowLeft'?-1:1)+list.length)%list.length];selectSide(next.dataset.bpSide);next.focus();});selectSide(ui.side);append(host,sides,bodies);
}
function mountSkirmish(){
 if(data.view!=='dashboard'||data.homeTab!=='skirmishes')return;const root=document.querySelector('.sk-page[data-sk-session]'),s=data.skirmishes?.find(s=>s.id===root?.dataset.skSession);if(!root||!s||!['battle','completed'].includes(s.stage)||root.querySelector('.bp-workspace'))return;
 const round=root.querySelector('.sk-round'),mission=root.querySelector('.sk-missions'),notes=root.querySelector('.sk-fold'),units=root.querySelector('.sk-unit-section'),originals=[...units?.querySelectorAll('.sk-unit')||[]],finish=root.querySelector('.sk-start'),header=root.querySelector('.sk-heading');
 const ctx=shell(view(null,s),root);append(ctx.panels.get('round'),round,finish);append(ctx.panels.get('mission'),mission);if(notes){notes.open=true;notes.querySelector(':scope > summary')?.setAttribute('hidden','');notes.classList.add('bp-native-notes');ctx.panels.get('operations').append(notes);}roster(view(null,s),ctx,originals);units?.remove();header?.classList.add('bp-match-heading');root.classList.add('bp-play-page');root.querySelector('.sk-top')?.classList.add('bp-backbar');window.UKI18n?.refresh(ctx.host);
}
function campaignMission(v,ctx){
 const host=ctx.panels.get('mission');for(const [key,en,ko]of [['deployment','Deployment','배치'],['objective','Objective','목표'],['crewSelection','Crew method','크루 방식']]){const row=window.MMCampaignPreparation?.selectedRow(v.c,v.s,key),raw=v.s[key];if(!row&&!raw)continue;const card=el('section','card bp-mission'),h=el('h2');h.innerHTML=L(en,ko);card.append(h);const name=el('strong');name.dataset.userText='';name.textContent=row?(window.UKI18n?.language==='en'?row.name:row.name_ko||row.name):raw;card.append(name);if(row){const p=el('div');p.innerHTML=window.MMRuleTerms?.prose(row.description_en||row.description,row.description,{kind:'scenarioEntries',row,edition:String(v.c.edition).toLowerCase()})||E(row.description||'');card.append(p);const b=el('button','btn small');b.type='button';b.innerHTML=L('Diagram & rules','도식·룰');b.dataset.bpAction=String(ctx.callbacks.length);ctx.callbacks.push(()=>window.MMRuleReference?.open('scenarioEntries',row,{edition:String(v.c.edition).toLowerCase(),activator:b}));card.append(b);}host.append(card);}
 if(!host.children.length){const p=el('p','bp-empty');p.dataset.userText='';p.textContent=v.s.scenario||txt('No mission recorded','미션 기록 없음');host.append(p);}
}
function mountCampaign(){
 if(data.view!=='campaign'||data.campaignTab!=='session-detail')return;const c=typeof campaign==='function'&&campaign(),s=c?.sessions?.find(s=>s.id===data.selectedBattleSession),root=document.querySelector('.cp-campaign-page');if(!root||!s||!['battle','post-battle','completed'].includes(s.stage)||root.querySelector('.bp-workspace'))return;
 const stack=root.querySelector('.stack');if(!stack)return;const native=[...stack.children],participants=[...stack.querySelectorAll('.cp-participant')],back=stack.querySelector('[data-cp=session-back]'),round=stack.querySelector('[data-cp=round-complete]')?.closest('.section-heading'),bottom=stack.querySelector('.cp-session-bottom'),v=view(c,s),ctx=shell(v,root);ctx.nativeParticipants=participants;
 root.insertBefore(heading(v,back),ctx.host);append(ctx.panels.get('round'),round,bottom);for(const node of native){if(node.classList.contains('ca-session-tools'))ctx.panels.get('round').append(node);else ctx.panels.get('operations').append(node);}stack.remove();roster(v,ctx);campaignMission(v,ctx);root.classList.add('bp-play-page','bp-campaign-play');window.UKI18n?.refresh(ctx.host);
}
function offsets(){const bar=document.querySelector('.main>.topbar'),style=bar&&getComputedStyle(bar),top=bar&&['fixed','sticky'].includes(style.position)?bar.getBoundingClientRect().height+Math.max(0,parseFloat(style.top)||0):0;document.querySelectorAll('.bp-workspace').forEach(n=>{n.style.setProperty('--bp-top',top+'px');n.style.setProperty('--bp-bar-height',(n.querySelector('.bp-bar')?.getBoundingClientRect().height||60)+'px');});}
function mount(){mountSkirmish();mountCampaign();const panel=document.querySelector('.bp-workspace [data-bp-panel=operations]');if(panel){for(const n of document.querySelectorAll('.content>.enroll-campaign-actions'))panel.prepend(n);}offsets();}
const original=render;render=function(...args){const result=original.apply(this,args);mount();return result;};window.addEventListener('resize',offsets);window.MMBattlePlay={mount};
})();
